use vstd::prelude::*;

verus! {

fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < result.len() ==> result[i] == 1,
{
    let n = a.len();
    let mut result: Vec<i32> = Vec::with_capacity(n);

    let mut i: usize = 0;
    while i < n
        invariant
            0 <= i <= n,
            result.len() == i,
            forall|j: int| 0 <= j < i ==> result[j] == 1,
        decreases n - i,
    {
        // After i iterations: result.len() == i and all elements so far are 1.
        result.push(1);
        i += 1;
    }

    result
}

}

